INSERT INTO bankapp_newsarticle VALUES(2,'Sustainable Finance: The Future of Banking','news_images/michele-purin-uWJo5rEhvo4-unsplash_wGRLxuG.jpg','2025-02-27 20:32:14.881917',12,replace(replace('As the world becomes more environmentally conscious, sustainable finance is gaining momentum. This approach not only supports eco-friendly projects but also promotes responsible investment. At SecureBank, we''re committed to driving positive change by offering green loans and sustainable investment options. Discover how you can invest in a better future while growing your wealth.\r\n\r\n🌿 Highlights:\r\n\r\n    Green loans for eco-friendly businesses\r\n    Investment opportunities in renewable energy\r\n    Our commitment to carbon neutrality by 2030\r\n\r\nReady to make a difference? Learn more about our sustainable finance options today!','\r',char(13)),'\n',char(10)));
INSERT INTO bankapp_newsarticle VALUES(3,'Digital Transformation: Enhancing Your Banking Experience','news_images/domenico-loia-hGV2TfOh0ns-unsplash.jpg','2025-02-27 20:37:31.017981',12,replace(replace('At SecureBank, we''re constantly innovating to provide you with the most seamless digital banking experience. Our new mobile app update includes enhanced security features, a more intuitive interface, and personalized financial insights. Banking has never been this easy or this smart!\r\n\r\n🚀 What''s New:\r\n\r\n    Biometric authentication for enhanced security\r\n    AI-powered financial insights tailored to your spending habits\r\n    24/7 customer support through our integrated chatbot\r\n\r\nUpdate your app now and take control of your finances wherever you are.','\r',char(13)),'\n',char(10)));
INSERT INTO bankapp_newsarticle VALUES(4,'Business Growth Made Easy with Our Flexible Loan Solutions','news_images/charles-forerunner-3fPXt37X6UQ-unsplash.jpg','2025-02-27 20:39:17.439540',12,replace(replace('Is your business ready to take the next big step? At SecureBank, we support entrepreneurs with customized loan solutions tailored to your business needs. Whether you''re looking to expand your team, invest in new equipment, or scale your operations, we''ve got you covered.\r\n\r\n💼 Why Choose SecureBank Business Loans:\r\n\r\n    Competitive interest rates and flexible repayment plans\r\n    Quick approval process with minimal paperwork\r\n    Dedicated financial advisors to guide you through every step\r\n\r\nEmpower your business with the financial support it deserves. Apply for a SecureBank business loan today!','\r',char(13)),'\n',char(10)));
