CREATE UNIQUE INDEX "bankapp_user_groups_user_id_group_id_a059b2be_uniq" ON "bankapp_user_groups" ("user_id", "group_id");
CREATE INDEX "bankapp_user_groups_user_id_e3c672ba" ON "bankapp_user_groups" ("user_id");
CREATE INDEX "bankapp_user_groups_group_id_c85194f5" ON "bankapp_user_groups" ("group_id");
