CREATE INDEX "bankapp_conversation_client_id_a989f987" ON "bankapp_conversation" ("client_id");
CREATE INDEX "bankapp_cannedmessage_category_id_f3efabf0" ON "bankapp_cannedmessage" ("category_id");
CREATE INDEX "bankapp_newsarticle_author_id_4299131b" ON "bankapp_newsarticle" ("author_id");
CREATE INDEX "bankapp_loanrequest_client_id_0143206d" ON "bankapp_loanrequest" ("client_id");
